insert into public.courses (slug,title,subject,description,published) values ('japanese-beginner','Japanese, made simple.','language','Start with the basics and take it one character at a time.',true);
insert into public.lessons (id,course_id,title,position,content,published) select '9e3f3448-ed79-4ab4-942d-fc9b40c218d4'::uuid, id, 'Your first character', 1, '{"subtitle":"Meet hiragana","character":"あ","sound":"a (ah)","description":"Japanese has three writing systems. Hiragana is a great place to start. This character is pronounced like the a in father.","answers":["I (ee)","A (ah)","U (oo)","E (eh)"],"correct":1}'::jsonb,true from public.courses where slug='japanese-beginner';
insert into public.lessons (id,course_id,title,position,content,published) select 'd909fd79-7715-4127-8bba-d4d3405f07c4'::uuid, id, 'One more sound', 2, '{"subtitle":"Build your hiragana","character":"い","sound":"i (ee)","description":"This hiragana character makes an ee sound, like the ee in see. Say it out loud a few times.","answers":["A (ah)","E (eh)","I (ee)","O (oh)"],"correct":2}'::jsonb,true from public.courses where slug='japanese-beginner';
insert into public.lessons (id,course_id,title,position,content,published) select '5456438b-d9cc-4179-91d7-04fe103b2e3b'::uuid, id, 'Say hello', 3, '{"subtitle":"Your first phrase","character":"こんにちは","sound":"konnichiwa","description":"This is a common way to say hello in Japanese. Try saying it: kon-nee-chee-wah.","answers":["Thank you","Goodbye","Good night","Hello"],"correct":3}'::jsonb,true from public.courses where slug='japanese-beginner';
